/*
Day #8 Twisted Sphere
https://openprocessing.org/sketch/2385842
https://mathober.com/
https://openprocessing.org/curation/87980
*/

const NUM = 19;

function setup() {
  createCanvas((S = max(windowWidth, windowHeight)), S, WEBGL);
  describe("layers of boxes rotating in different speeds and different sizes forming a twisted sphere with a gradient from top purple to bottom blue");
  frameRate(60);
  noStroke();
}

function draw() {
  background(0, 0, 8);
  rotateX(-0.4);
  orbitControl();

  // lights();
  ambientLight(255, 255, 255);
  spotLight(
    color("white"),
    createVector(height / 4, -height, height),
    createVector(-height / 4, height / 2, -height / 2).normalize(),
    PI / 3,
    10
  );

  const RAD = max(width, height) * 0.5;
  for (let i = 0; i < NUM; i++) {
    push();
    translate(0, (i * RAD) / NUM - RAD / 2, 0);
    rotateY(-frameCount / 43 + (i / sin(frameCount / 321)) * PI);
    const ang = PI * (map(i, 0, NUM - 1, 1, NUM * 2 - 1) / (NUM * 2));
    const rd = sin(ang) * RAD;
		const wh = Math.sqrt(rd*rd+rd*rd)/1.5;
    fill(64, 8, 64 + (NUM - i) * (192 / NUM), 128);
    box(wh, RAD / NUM, wh);
    pop();
  }
}
